from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up.
left_gear_ = Motor(Port.C, Direction.CLOCKWISE)
right_gear_ = Motor(Port.D, Direction.CLOCKWISE)
eldertreespeed = 250
prime_hub = PrimeHub()
my_69 = Motor(Port.E, Direction.CLOCKWISE)
my_41 = Motor(Port.A, Direction.COUNTERCLOCKWISE)
drive_baaaaaaase = DriveBase(my_41, my_69, 62.4, 128)

def forest_elder():
    drive_baaaaaaase.straight(330)
    right_gear_.run_angle(200, -60)
    drive_baaaaaaase.straight(-170)
    right_gear_.run_angle(100, 70)
    drive_baaaaaaase.straight(-110)
    right_gear_.run_angle(200, -100)
    drive_baaaaaaase.turn(-22.5)
    drive_baaaaaaase.straight(660)
    drive_baaaaaaase.turn(112.5)
    drive_baaaaaaase.straight(125)
    left_gear_.run_angle(500, 50)
    drive_baaaaaaase.straight(-10)
    left_gear_.run_angle(500, -50)
    drive_baaaaaaase.straight(-100)
    drive_baaaaaaase.turn(80)
    drive_baaaaaaase.straight(600)

def DrivebaseSpeed():
    drive_baaaaaaase.settings(straight_speed=eldertreespeed)

def biocentric():
    drive_baaaaaaase.straight(290)
    drive_baaaaaaase.settings(straight_speed=200)
    right_gear_.run_angle(500, 300)
    left_gear_.run_angle(500, -550)
    drive_baaaaaaase.straight(-100)
    drive_baaaaaaase.settings(straight_speed=400)
    right_gear_.run_angle(500, -300)
    drive_baaaaaaase.straight(-300)
    left_gear_.run_angle(500, 550)

def DRIVEBASE_SPEED():
    drivebaaaase.settings(straight_speed=SPEED)

def DRIVEBASE_SPEED_2():
    drivebaaaase.settings(straight_speed=SPEED)


# The main program starts here.
drive_baaaaaaase.use_gyro(True)
biocentric()
wait(1000)
forest_elder()
